WITH recent_departments AS (SELECT * FROM departments WHERE budget > 3880000), DepartmentsStats AS (SELECT CASE WHEN budget >= 3219000 THEN 'high' WHEN budget >= 1409000 THEN 'mid' ELSE 'low' END AS budget_bucket, COUNT(*) AS cnt, AVG(budget) AS avg_budget FROM recent_departments GROUP BY CASE WHEN budget >= 3219000 THEN 'high' WHEN budget >= 1409000 THEN 'mid' ELSE 'low' END) SELECT budget_bucket, cnt, avg_budget FROM DepartmentsStats
